const page = "<!doctype html>\n<html lang=\"pt-BR\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n    <meta name=\"description\" content=\"Portfólio de Prof. Henrique Santos — desenvolvedor de software e instrutor de tecnologia.\" />\n    <title>Prof. Henrique Santos | Portfólio</title>\n    <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\" />\n    <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin />\n    <link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=Space+Grotesk:wght@500;600;700&display=swap\" rel=\"stylesheet\" />\n    <style>:root{--ink:#15243d;--muted:#607087;--blue:#1769e8;--blue-dark:#0b3d91;--green:#1d735d;--pale:#f6f8fc;--line:#dfe6f0;--card:#fff;--shadow:0 20px 45px rgba(31,56,91,.10)}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--pale);color:var(--ink);font-family:Inter,Arial,sans-serif;font-size:16px;line-height:1.6}.container{width:min(1120px,calc(100% - 40px));margin:auto}.skip-link{position:absolute;left:-999px}.skip-link:focus{left:12px;top:12px;z-index:10;background:white;padding:8px}.header{height:74px;background:rgba(246,248,252,.89);backdrop-filter:blur(14px);border-bottom:1px solid #edf0f4;position:sticky;top:0;z-index:10}.nav{height:100%;display:flex;align-items:center;justify-content:space-between}.brand{display:flex;align-items:center;gap:10px;color:var(--ink);font-weight:800;text-decoration:none;font-size:17px}.brand-mark{width:31px;height:31px;border-radius:9px;display:grid;place-items:center;background:var(--blue);color:#fff;font-size:12px;box-shadow:0 5px 14px #1769e844}.brand-dot{color:var(--blue)}.nav-links{display:flex;gap:28px}.nav-links a{color:#536177;text-decoration:none;font-size:14px;font-weight:600}.nav-links a:hover{color:var(--blue)}.menu-button{display:none;border:0;background:transparent;font-size:24px;color:var(--ink)}.hero{overflow:hidden;background:linear-gradient(130deg,#f6f9fe 0%,#eef6f6 100%);min-height:610px;padding:92px 0 72px}.hero-grid{display:grid;grid-template-columns:1.08fr .92fr;align-items:center;gap:60px}.eyebrow,.section-kicker{font-size:12px;letter-spacing:.15em;font-weight:800;color:var(--green);margin:0 0 18px}.eyebrow{color:var(--blue);display:flex;align-items:center;gap:8px}.eyebrow span{background:#49bd99;width:8px;height:8px;border-radius:50%;box-shadow:0 0 0 5px #49bd9920}h1,h2,h3{font-family:'Space Grotesk',Inter,sans-serif;line-height:1.08;margin:0}h1{font-size:clamp(42px,5vw,68px);letter-spacing:-.055em;max-width:660px}h1 em,h2 em{font-style:normal;color:var(--blue)}.hero-text{font-size:17px;max-width:550px;color:var(--muted);margin:26px 0}.hero-text strong{color:var(--ink)}.hero-actions{display:flex;gap:13px;flex-wrap:wrap}.button{display:inline-flex;align-items:center;gap:18px;border-radius:11px;padding:13px 18px;text-decoration:none;font-size:14px;font-weight:700;transition:.2s}.button:hover{transform:translateY(-2px)}.primary{background:var(--blue);box-shadow:0 11px 20px #1769e837;color:white}.ghost{border:1px solid #cdd9e8;color:var(--ink);background:#fff}.tech-row{display:flex;gap:8px;flex-wrap:wrap;margin-top:31px}.tech-row span{font-size:12px;color:#536177;font-weight:600;border:1px solid #d9e2ec;background:#ffffff80;padding:5px 10px;border-radius:20px}.hero-visual{height:390px;position:relative}.code-window{position:absolute;inset:45px 0 0 28px;background:#132744;border:1px solid #29517a;border-radius:18px;color:#a7c3de;padding:0 26px;box-shadow:var(--shadow);transform:rotate(-2deg);z-index:2}.window-top{height:54px;display:flex;align-items:center;gap:7px;border-bottom:1px solid #29415e}.window-top i{width:9px;height:9px;border-radius:50%;background:#ff5f57}.window-top i:nth-child(2){background:#ffbd2e}.window-top i:nth-child(3){background:#28c940}.window-top b{font-family:Inter;font-size:12px;font-weight:500;color:#95afc8;margin-left:8px}.code-lines{font-family:monospace;font-size:14px;line-height:2.2;padding-top:28px}.code-lines b{color:#68bbf5}.accent{color:#6ed2a8}.orb{position:absolute;border-radius:50%;filter:blur(.2px)}.orb-one{width:270px;height:270px;background:#5cbeaa35;right:-45px;top:0}.orb-two{width:130px;height:130px;background:#2a7df834;left:-20px;bottom:0}.floating-card{position:absolute;z-index:3;background:#fff;border:1px solid #e5edf5;border-radius:12px;padding:11px 15px;box-shadow:0 13px 30px #233c5721;display:flex;align-items:center;gap:10px}.floating-card>span{width:29px;height:29px;border-radius:8px;display:grid;place-items:center;background:#e3f4ef;color:var(--green);font-size:17px}.floating-card small{display:block;color:#8290a2;font-size:10px}.floating-card b{display:block;font-size:12px}.maker-card{right:-12px;top:23px}.app-card{left:-12px;bottom:25px}.app-card>span{color:var(--blue);background:#e7f0ff}.section{padding:112px 0}.about{background:#fff}.about-grid{display:grid;grid-template-columns:.9fr 1.1fr;gap:100px}.about h2,.section-heading h2{font-size:clamp(32px,4vw,49px);letter-spacing:-.05em}.about-text p{color:var(--muted);margin:0 0 18px}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;border-top:1px solid var(--line);padding-top:26px;margin-top:31px}.stats b{display:block;color:var(--blue);font:700 27px 'Space Grotesk'}.stats span{display:block;font-size:11px;line-height:1.35;color:#79879a;margin-top:3px}.projects{background:var(--pale)}.section-heading{display:flex;justify-content:space-between;align-items:end;gap:30px;margin-bottom:38px}.section-heading>p{color:var(--muted);max-width:310px;margin:0;font-size:14px}.tabs{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:23px}.tab{border:1px solid var(--line);background:#fff;color:#617087;font:600 13px Inter;padding:10px 14px;border-radius:9px;cursor:pointer}.tab.active{background:var(--ink);border-color:var(--ink);color:white}.project-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:18px}.project-card{background:var(--card);min-height:325px;border:1px solid #e6edf5;border-radius:17px;padding:26px;box-shadow:0 4px 10px #213c6110;transition:.25s}.project-card:hover{box-shadow:var(--shadow);transform:translateY(-4px)}.project-card.hidden{display:none}.card-top,.card-footer{display:flex;justify-content:space-between;align-items:center}.project-number{font:700 13px 'Space Grotesk';color:#91a0b3}.tag,.timeline-label{font-size:10px;letter-spacing:.08em;padding:4px 7px;border-radius:5px;font-weight:800}.tag.blue{color:var(--blue);background:#eaf2ff}.tag.violet{color:#6e51be;background:#f0ecff}.tag.green,.timeline-label{color:var(--green);background:#e5f4ee}.project-icon{width:52px;height:52px;border-radius:15px;display:grid;place-items:center;margin:39px 0 23px;font-size:25px;font-weight:bold}.blue-bg{color:var(--blue);background:#e7f0ff}.violet-bg{color:#7655c9;background:#f0ecff}.green-bg{color:var(--green);background:#e5f4ee}.project-card h3{font-size:25px;letter-spacing:-.035em}.project-card p{font-size:14px;color:var(--muted);max-width:410px;margin:11px 0 28px}.card-footer{border-top:1px solid #edf1f5;padding-top:16px;color:#718197;font-size:11px;font-weight:700}.arrow{color:var(--blue);font-size:20px}.journey{background:#fff}.timeline{max-width:900px;margin:55px auto 0;position:relative}.timeline:before{content:'';position:absolute;top:10px;bottom:10px;left:50%;width:1px;background:#d9e5e8}.timeline-item{display:grid;grid-template-columns:1fr 36px 1fr;position:relative;margin-bottom:30px}.timeline-item:nth-child(even) .timeline-date{grid-column:3;text-align:left;padding-left:26px}.timeline-item:nth-child(even) .timeline-card{grid-column:1;grid-row:1;text-align:right}.timeline-item:nth-child(even) .timeline-card p{margin-left:auto}.timeline-date{padding-top:15px;text-align:right;padding-right:26px;color:#7c8b9b;font-size:11px;font-weight:800;letter-spacing:.1em}.timeline-dot{grid-column:2;grid-row:1;place-self:start;margin-top:15px;width:12px;height:12px;background:#fff;border:3px solid #92b8b0;border-radius:50%;z-index:1}.current .timeline-dot{width:16px;height:16px;margin-top:13px;border-color:var(--blue);box-shadow:0 0 0 5px #1769e81a}.timeline-card{grid-column:3;background:var(--pale);border:1px solid #e8eef3;border-radius:12px;padding:20px 21px}.timeline-card h3{font-size:19px;margin-top:9px}.timeline-card h4{font-size:13px;color:var(--blue);margin:4px 0;font-weight:700}.timeline-card p{font-size:13px;color:var(--muted);margin:10px 0 0;max-width:340px}.contact{color:white;text-align:center;padding:98px 0;background:radial-gradient(circle at 14% 70%,#238571 0,transparent 30%),radial-gradient(circle at 88% 20%,#1c68d0 0,transparent 28%),#132a49}.contact .section-kicker{color:#80ddc3}.contact h2{font-size:clamp(38px,5vw,60px);letter-spacing:-.055em}.contact>p{color:#c0d0df;margin:20px auto 26px}.contact-inner>.button{margin:6px}.light{background:#fff;color:var(--ink)}.github-link{display:block;margin-top:24px;color:#bcd5ef;font-weight:600;font-size:13px;text-decoration:none}footer{background:#0e2039;color:#98aabe;padding:19px 0;font-size:11px}footer .container{display:flex;justify-content:space-between;gap:12px}\n@media(max-width:760px){.container{width:min(100% - 32px,560px)}.header{height:64px}.menu-button{display:block;z-index:2}.nav-links{display:none;position:absolute;top:63px;left:0;right:0;padding:20px;background:#fff;border-bottom:1px solid var(--line);box-shadow:0 15px 20px #14284414;flex-direction:column;gap:15px}.nav-links.open{display:flex}.hero{padding:70px 0 50px;min-height:auto}.hero-grid,.about-grid{grid-template-columns:1fr;gap:45px}.hero-visual{height:315px;margin:0 4px}.code-window{inset:20px 0 0 10px;padding:0 18px}.code-lines{font-size:12px}.maker-card{right:-6px;top:7px}.app-card{left:-5px;bottom:4px}.section{padding:76px 0}.about-grid{gap:33px}.section-heading{display:block;margin-bottom:27px}.section-heading>p{margin-top:16px}.stats{gap:8px}.stats b{font-size:23px}.project-grid{grid-template-columns:1fr}.project-card{min-height:280px}.timeline{margin-top:38px}.timeline:before{left:6px}.timeline-item,.timeline-item:nth-child(even){display:grid;grid-template-columns:24px 1fr;gap:0}.timeline-dot,.current .timeline-dot{grid-column:1;grid-row:1;margin:6px 0 0;place-self:start}.timeline-date,.timeline-item:nth-child(even) .timeline-date{grid-column:2;grid-row:1;text-align:left;padding:0 0 9px}.timeline-card,.timeline-item:nth-child(even) .timeline-card{grid-column:2;grid-row:2;text-align:left}.timeline-item:nth-child(even) .timeline-card p{margin-left:0}.contact{padding:77px 0}.contact h2 br{display:none}footer .container{flex-direction:column;text-align:center}.hero-text{font-size:16px}}\n</style>\n  </head>\n  <body>\n    <a class=\"skip-link\" href=\"#conteudo\">Pular para o conteúdo</a>\n    <header class=\"header\">\n      <nav class=\"nav container\" aria-label=\"Navegação principal\">\n        <a class=\"brand\" href=\"#inicio\" aria-label=\"Início\"><span class=\"brand-mark\">&lt;/&gt;</span><span>Prof. Henrique<span class=\"brand-dot\">.</span></span></a>\n        <button class=\"menu-button\" aria-label=\"Abrir menu\" aria-expanded=\"false\">☰</button>\n        <div class=\"nav-links\">\n          <a href=\"#sobre\">Sobre</a><a href=\"#projetos\">Projetos</a><a href=\"#trajetoria\">Trajetória</a><a href=\"#contato\">Contato</a>\n        </div>\n      </nav>\n    </header>\n\n    <main id=\"conteudo\">\n      <section id=\"inicio\" class=\"hero\">\n        <div class=\"container hero-grid\">\n          <div class=\"hero-copy\">\n            <p class=\"eyebrow\"><span></span> Desenvolvedor &amp; educador</p>\n            <h1>Ideias que saem do <em>código</em> e ganham o mundo.</h1>\n            <p class=\"hero-text\">Sou <strong>Henrique Santos</strong>, desenvolvedor de software e instrutor de tecnologia. Transformo lógica de programação e hardwares educacionais em soluções práticas.</p>\n            <div class=\"hero-actions\"><a class=\"button primary\" href=\"#projetos\">Ver projetos <span>↓</span></a><a class=\"button ghost\" href=\"https://github.com/HenriqueSanttos\" target=\"_blank\" rel=\"noreferrer\">GitHub <span>↗</span></a></div>\n            <div class=\"tech-row\" aria-label=\"Tecnologias principais\"><span>Flutter</span><span>Dart</span><span>Node.js</span><span>Arduino</span></div>\n          </div>\n          <div class=\"hero-visual\" aria-hidden=\"true\">\n            <div class=\"orb orb-one\"></div><div class=\"orb orb-two\"></div>\n            <div class=\"code-window\"><div class=\"window-top\"><i></i><i></i><i></i><b>solucao.dart</b></div><div class=\"code-lines\"><span><b>class</b> Solucao {</span><span>&nbsp;&nbsp;<b>final</b> ideia =</span><span>&nbsp;&nbsp;&nbsp;&nbsp;Tecnologia<span class=\"accent\">.acessivel()</span>;</span><span>&nbsp;&nbsp;<b>final</b> impacto =</span><span>&nbsp;&nbsp;&nbsp;&nbsp;ideia<span class=\"accent\">.emAcao()</span>;</span><span>}</span></div></div>\n            <div class=\"floating-card maker-card\"><span>◌</span><div><small>Cultura maker</small><b>Aprender fazendo</b></div></div>\n            <div class=\"floating-card app-card\"><span>▣</span><div><small>Mobile &amp; web</small><b>Produtos digitais</b></div></div>\n          </div>\n        </div>\n      </section>\n\n      <section id=\"sobre\" class=\"section about\"><div class=\"container about-grid\"><div><p class=\"section-kicker\">01 — SOBRE MIM</p><h2>Tecnologia só faz sentido quando aproxima pessoas.</h2></div><div class=\"about-text\"><p>Sou bacharel em Agrocomputação (2021) com experiência que transita entre o mercado de tecnologia aplicada e a educação. Comecei atuando na linha de frente como Analista de Implantação de Projetos e hoje atuo como Instrutor de Formação Profissional no SENAI.</p><p>Meu foco é desenvolver aplicações escaláveis e criar materiais didáticos e projetos maker de código aberto. Mais que automatizar: quero tornar a tecnologia acessível e aplicável na sala de aula e no dia a dia.</p><div class=\"stats\"><div><b>04+</b><span>tecnologias-chave</span></div><div><b>2021</b><span>formação em Agrocomputação</span></div><div><b>2</b><span>frentes de impacto</span></div></div></div></div></section>\n\n      <section id=\"projetos\" class=\"section projects\"><div class=\"container\"><div class=\"section-heading\"><div><p class=\"section-kicker\">02 — PROJETOS</p><h2>Construindo para o agora.<br /><em>Ensinando para o próximo.</em></h2></div><p>Uma seleção de produtos digitais e iniciativas abertas que conectam software, educação e impacto prático.</p></div><div class=\"tabs\" role=\"tablist\" aria-label=\"Categorias de projetos\"><button class=\"tab active\" role=\"tab\" aria-selected=\"true\" data-filter=\"dev\">⌘ Desenvolvimento mobile &amp; web</button><button class=\"tab\" role=\"tab\" aria-selected=\"false\" data-filter=\"maker\">◌ Educacionais &amp; open-source</button></div><div class=\"project-grid\">\n        <article class=\"project-card dev\"><div class=\"card-top\"><span class=\"project-number\">01</span><span class=\"tag blue\">FLUTTER · DART</span></div><div class=\"project-icon blue-bg\">⌁</div><h3>Ponto Rápido</h3><p>Aplicativo de gestão corporativa, com foco em uma experiência ágil e organizada para equipes.</p><div class=\"card-footer\"><span>Arquitetura &amp; desenvolvimento</span><span class=\"arrow\">↗</span></div></article>\n        <article class=\"project-card dev\"><div class=\"card-top\"><span class=\"project-number\">02</span><span class=\"tag violet\">WEB PLATFORM</span></div><div class=\"project-icon violet-bg\">✦</div><h3>Festô</h3><p>Marketplace de eventos criado do zero, da modelagem de dados à estruturação da plataforma.</p><div class=\"card-footer\"><span>Produto &amp; banco de dados</span><span class=\"arrow\">↗</span></div></article>\n        <article class=\"project-card maker hidden\"><div class=\"card-top\"><span class=\"project-number\">03</span><span class=\"tag green\">ARDUINO · ESP32</span></div><div class=\"project-icon green-bg\">⌘</div><h3>Agro-Hacking</h3><p>Kit aberto e sustentável de automação agrícola para aprender fazendo, com sensores acessíveis.</p><div class=\"card-footer\"><span>Educação &amp; cultura maker</span><span class=\"arrow\">↗</span></div></article>\n      </div></div></section>\n\n      <section id=\"trajetoria\" class=\"section journey\"><div class=\"container\"><div class=\"section-heading\"><div><p class=\"section-kicker\">03 — TRAJETÓRIA</p><h2>Uma carreira guiada pela <em>curiosidade.</em></h2></div><p>Da implantação de tecnologia no campo à formação de novos profissionais.</p></div><div class=\"timeline\"><article class=\"timeline-item current\"><div class=\"timeline-date\">ATUALMENTE</div><div class=\"timeline-dot\"></div><div class=\"timeline-card\"><span class=\"timeline-label\">EDUCAÇÃO</span><h3>Instrutor de Formação Profissional</h3><h4>SENAI</h4><p>Criação de planos de aula, guias técnicos e instrução de tecnologias industriais e educacionais.</p></div></article><article class=\"timeline-item\"><div class=\"timeline-date\">2026</div><div class=\"timeline-dot\"></div><div class=\"timeline-card\"><span class=\"timeline-label\">PRODUTO DIGITAL</span><h3>Desenvolvimento de Produtos Digitais</h3><h4>Ponto Rápido &amp; Festô</h4><p>Idealização e criação ativa de aplicações que resolvem problemas reais.</p></div></article><article class=\"timeline-item\"><div class=\"timeline-date\">ANTERIOR</div><div class=\"timeline-dot\"></div><div class=\"timeline-card\"><span class=\"timeline-label\">TECNOLOGIA APLICADA</span><h3>Analista de Implantação de Projetos</h3><h4>Solinftec</h4><p>Experiência corporativa direta com implantação de tecnologia de ponta.</p></div></article><article class=\"timeline-item\"><div class=\"timeline-date\">SET. 2021</div><div class=\"timeline-dot\"></div><div class=\"timeline-card\"><span class=\"timeline-label\">FORMAÇÃO</span><h3>Bacharel em Agrocomputação</h3><h4>Graduação</h4><p>A base multidisciplinar que conecta o digital às aplicações do mundo real.</p></div></article></div></div></section>\n      <section id=\"contato\" class=\"contact\"><div class=\"container contact-inner\"><p class=\"section-kicker\">04 — VAMOS CONVERSAR</p><h2>Tem uma ideia que<br />merece sair do papel?</h2><p>Vamos construir algo útil, acessível e memorável juntos.</p><a class=\"button light\" href=\"mailto:contato@exemplo.com\">Enviar uma mensagem <span>↗</span></a><a class=\"github-link\" href=\"https://github.com/HenriqueSanttos\" target=\"_blank\" rel=\"noreferrer\">◉ github.com/HenriqueSanttos</a></div></section>\n    </main>\n    <footer><div class=\"container\"><span>© 2026 Prof. Henrique Santos</span><span>Feito com intenção, código e café.</span></div></footer>\n    <script>// Interações simples do portfólio: menu móvel e alternância de categorias.\nconst menuButton = document.querySelector('.menu-button');\nconst navLinks = document.querySelector('.nav-links');\nmenuButton.addEventListener('click', () => {\n  const open = navLinks.classList.toggle('open');\n  menuButton.setAttribute('aria-expanded', open);\n  menuButton.textContent = open ? '×' : '☰';\n});\ndocument.querySelectorAll('.nav-links a').forEach(link => link.addEventListener('click', () => { navLinks.classList.remove('open'); menuButton.setAttribute('aria-expanded', 'false'); menuButton.textContent = '☰'; }));\nconst tabs = document.querySelectorAll('.tab');\nconst cards = document.querySelectorAll('.project-card');\ntabs.forEach(tab => tab.addEventListener('click', () => {\n  const filter = tab.dataset.filter;\n  tabs.forEach(item => { item.classList.toggle('active', item === tab); item.setAttribute('aria-selected', item === tab); });\n  cards.forEach(card => card.classList.toggle('hidden', !card.classList.contains(filter)));\n}));\n</script>\n  </body>\n</html>\n";
export default { async fetch() { return new Response(page, { headers: { 'content-type': 'text/html; charset=UTF-8', 'cache-control': 'public, max-age=300' } }); } };
